create or replace view KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_VIEW.V_UDF_PROGNOSE_WHATIF_2(
	MANDANT_ID COMMENT 'Mandant_2 im DWH.',
	ART_ID COMMENT 'Input: Artikel_2 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1.',
	WUP_ID COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ANGEBOT_ID COMMENT 'Offer/Angebot_2-ID.',
	DAT_VON COMMENT 'YYYY-MM_2-DD // Aktion_2 gültig von.',
	DAT_BIS COMMENT 'YYYY-MM_2-DD // Aktion_2 gültig bis.',
	MENGE_PROGNOSE_BASIS COMMENT 'Basisverkaufsmenge für zusätzliche Deltaverkaufsberechnungen.',
	MENGE_PROGNOSE_SAISON COMMENT 'Nettoverkaufsmenge wegen Saisonalität.',
	MENGE_PROGNOSE_FEIERTAG COMMENT 'Nettoverkaufsmenge wegen Feiertagen.',
	MENGE_PROGNOSE_PREISAENDERUNG COMMENT 'Nettoverkaufsmenge wegen Preisänderungen.',
	MENGE_PROGNOSE_KAUFANREIZE COMMENT 'Nettoverkaufsmenge wegen vorausgesetzten Kaufanreizen.',
	MENGE_PROGNOSE_UPLIFT COMMENT 'Nettoverkaufsmenge wegen Effekt durch Angebotsart-Uplift.',
	MENGE_PROGNOSE_WERBEMITTEL COMMENT 'Nettoverkaufsmenge wegen Effekt aller Werbemittel.',
	MENGE_PROGNOSE_PRAEMIENKAUFANREIZE COMMENT 'Nettoverkaufsmenge wegen Prämienkaufanreizen.',
	MENGE_PROGNOSE_KUNDENKARTE COMMENT 'Nettoverkaufsmenge wegen Kundenkarte.',
	MENGE_PROGNOSE_VERFUEGBARKEIT COMMENT 'Nettoverkaufsmenge wegen Verfügbarkeit.',
	MENGE_PROGNOSE_KANNIBALISIERUNG COMMENT 'Nettoverkaufsmenge wegen Kannibalisierung.',
	MENGE_PROGNOSE_VERBUND COMMENT 'Nettoverkaufsmenge wegen Verbundeffekt.',
	MENGE_PROGNOSE_FAKTOREN COMMENT 'Nettoverkaufsmenge aus anderen Bedarfseinflussfaktoren.',
	MENGE_PROGNOSE_GESAMT COMMENT 'Nettoverkaufsmenge gesamt.',
	DAT_ERSTELLUNG COMMENT 'Anlagedatum aus dat_erstellung.',
	DAT_BELADUNG COMMENT 'Beladungsdatum (DWH).',
	DAT_PROGNOSE_WERBUNG_ZULETZT_GESTEUERT COMMENT 'Datum der letzten manuellen  Prognosesteuerung für die Werbeprognose.',
	DAT_PROGNOSE_NORMAL_ZULETZT_GESTEUERT COMMENT 'Datum der letzten Prognosesteuerung für die Normalprognose.',
	PROGNOSE_OFFER_NULLWERT_FG COMMENT 'Einfluss auf Prognose durch Offer = 0.',
	PROGNOSE_PREIS_NULLWERT_FG COMMENT 'Einfluss auf Prognose durch Preis = 0.',
	PROGNOSE_PREIS_FAKTOR_FG COMMENT 'Einfluss auf Prognose durch Preis < 0.',
	PROGNOSE_TACTIC_NULLWERT_FG COMMENT 'Einfluss auf Prognose durch Tactic = 0.',
	MENGE_PROGNOSE_FAKTOR_FG COMMENT 'Einfluss aller Faktoren auf die Prognose < 0.',
	MENGE_PROGNOSE_NULLWERT_FG COMMENT 'Einfluss aller Faktoren auf die Prognose = 0.',
	QUELLE_ALT_PRIOREN_FG COMMENT 'ACHTUNG: Abgelöst mit der Einführung der ANZ_A_PRIORI_PARAMETER_* Spalten. Nur noch gültig/gefüllt für historische Daten davor. Flag: Sagt aus, ob alternative a-priori Parameter (Prioren) verwendet wurden als die zum Artikel_2 eigenen. Andere sind entweder Referenzartikel, hierarchische Prioren oder global-default Einstellungen. 1 bedeutet, dass mindestens eine_2 der erwähnten Alternativen zur Berechnung der Prognose herangezogen wurde.',
	ANZ_PRIOR_GESAMT COMMENT 'Anzahl aller verfügbaren Prioren zur Prognoseberechnung. Prior ist die übliche Abkürzung für a priori Wahrscheinlichkeit. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\nSAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\nWenig historische Daten → Parameterschätzungen näher an Priors\nViele historische Daten → Parameterschätzungen näher an Daten\nDie berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_EIGEN COMMENT 'Anzahl der verfügbaren Prioren, die auf der eigenen Historie basieren. Höchste Präferenz. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\nSAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\nWenig historische Daten → Parameterschätzungen näher an Priors\nViele historische Daten → Parameterschätzungen näher an Daten\nDie berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_REF COMMENT 'Anzahl der verfügbaren Prioren, die auf der Referenzhistorie basieren. Erst-niedrigere Präferenz, nach den eigenen Prioren. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\nSAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\nWenig historische Daten → Parameterschätzungen näher an Priors\nViele historische Daten → Parameterschätzungen näher an Daten\nDie berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_HPR COMMENT 'Anzahl der verfügbaren Prioren, die auf hierarchischen Prioren (HPR) basieren (z.B. WG, WUG_2 bzw. WGI (Warengruppenindex)). Hierarchische Kriterien die indirekt zum Artikel_2 gehören, wie z.B. Warengruppe. Zweit-niedrigere Präferenz, nach den eigenen und Referenzartikeln. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\nSAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\nWenig historische Daten → Parameterschätzungen näher an Priors\nViele historische Daten → Parameterschätzungen näher an Daten\nDie berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	ANZ_PRIOR_DEFAULT COMMENT 'Anzahl der verfügbaren Prioren, die auf default-Werten basieren. Niedrigste Präferenz, nach den eigenen, Referenzartikeln und hierarchischen Prioren. Verfügbar, weil es nicht die tatsächliche Anzahl der verwendeten Prioren ist, sondern die, die dem Modell zum Zeitpunkt der Prognoseerstellung zur Verfügung standen.\nSAP UDF kann fehlende Informationen durch allgemeine bestmögliche Schätzungen (Prioren) behandeln. Bei der Berechnung der Parameterschätzungen des Bedarfsmodells balanciert UDF a priori und historische Daten:\nWenig historische Daten → Parameterschätzungen näher an Priors\nViele historische Daten → Parameterschätzungen näher an Daten\nDie berechneten Parameterschätzungen dienen als Input für die Berechnung der Prognose.',
	DK_FG COMMENT 'Flag gibt an, ob eine_2 Aktion_2 (Offer) in der UDF-Prognose durch die sogenannte Doorkeeper-Logik herausgefiltert wurde.\n1 (Ja): Die Aktion_2 wurde durch den Doorkeeper ausgefiltert und ist somit in UDF inaktiv.\n0 (Nein): Die Aktion_2 wurde nicht ausgefiltert und bleibt in UDF aktiv.\nQuelle ist das Feld DK_RELEVANCE aus der SAP Tabelle ZUDF_OFRWBS_DATA. Mapping: wenn X=1, sonst 0.'
) as 
    SELECT 
        mandant_id,
        art_id,
        wup_id,
        nb_id,
        angebot_id,
        dat_von,
        dat_bis,
        menge_prognose_basis,
        menge_prognose_saison,
        menge_prognose_feiertag,
        menge_prognose_preisaenderung,
        menge_prognose_kaufanreize,
        menge_prognose_uplift,
        menge_prognose_werbemittel,
        menge_prognose_praemienkaufanreize,
        menge_prognose_kundenkarte,
        menge_prognose_verfuegbarkeit,
        menge_prognose_kannibalisierung,
        menge_prognose_verbund,
        menge_prognose_faktoren,
        menge_prognose_gesamt,
        dat_erstellung,
        dat_beladung,
        dat_prognose_werbung_zuletzt_gesteuert,
        dat_prognose_normal_zuletzt_gesteuert,
        prognose_offer_nullwert_fg,
        prognose_preis_nullwert_fg,
        prognose_preis_faktor_fg,
        prognose_tactic_nullwert_fg,
        menge_prognose_faktor_fg,
        menge_prognose_nullwert_fg,
        quelle_alt_prioren_fg,
        anz_prior_gesamt,
        anz_prior_eigen,
        anz_prior_ref,
        anz_prior_hpr,
        anz_prior_default,
        dk_fg

FROM DBP_DATA.UDF_PROGNOSE_WHATIF_2 ;
